import sys

def solve():
    T = int(sys.stdin.readline())
    for _ in range(T):
        n = int(sys.stdin.readline())
        p = [0] * n
        if n == 2:
            print("2 1")
            continue
        p[0] = 2
        p[1] = 1
        for i in range(2, n):
            p[i] = i + 1
        p[n-1] = 2
        for i in range(2, n):
            if p[i] == i + 1:
                p[i] = i - 1
                break
        print(' '.join(map(str, p)))

solve()
